import{_ as a,a0 as r,w as o,s as f,ao as s,I as n,x as e,a1 as p,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"Ubuntu每日小技巧：通过PPA升级你的LibreOffice | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu每日小技巧：通过PPA升级你的LibreOffice | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu每日小技巧：通过PPA升级你的LibreOffice | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu每日小技巧：通过PPA升级你的LibreOffice | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips–Update To LibreOffice Latest In Ubuntu Via PPA","title":"Ubuntu每日小技巧：通过PPA升级你的LibreOffice","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips–Update To LibreOffice Latest In Ubuntu Via PPA.md","filePath":"[post].md"}'),b={name:"201311/Daily Ubuntu Tips–Update To LibreOffice Latest In Ubuntu Via PPA.md"};function l(d,t,L,T,P,m){const i=r("Link");return o(),f("div",null,[t[11]||(t[11]=s(`<h1 id="ubuntu每日小技巧-通过ppa升级你的libreoffice" tabindex="-1">Ubuntu每日小技巧：通过PPA升级你的LibreOffice <a class="header-anchor" href="#ubuntu每日小技巧-通过ppa升级你的libreoffice" aria-label="Permalink to “Ubuntu每日小技巧：通过PPA升级你的LibreOffice”">​</a></h1><p>对于每一个你新安装的Ubuntu系统，你都会拥有一个可以让你办公的办公工具——LibreOffice。很多人都知道微软公司的的Word、Excel、PowerPoint和Outlook，但是很少有人知道LibreOffice。</p><p>LibreOffice靠来自全世界的志愿者来维护，由一个慈善基金会支持。它是Linux社区的一款主要的免费办公工具。它可以安装在Windows，Mac OS X和Linux等系统的计算机上。</p><p>就在5天前（译注：好吧，这个翻译稿拖了5天了~~，原文为“今天”。），一个新的版本将面向公众开放了。Windows，Mac OS X和Linux用户可以直接从下载页面下载最新版本了。</p><p>Ubuntu用户拥有添加LibreOffice软件仓库到自己的电脑来安装升级最新版的优势。如果你想要在最新版本可用时最快的得到它，这种方法将会很有用。</p><p>最新的LibreOffice套装版本是4.1。每一个后续的版本可以立即在4.1的仓库中找到，直到新的主线版本比如4.2的推出。</p><p>所以，为了在Ubuntu中自动的升级，请添加下面的软件仓库地址。</p><pre><code>sudo add-apt-repository ppa:libreoffice/ppa
</code></pre><p>接着，运行如下命令来升级最新的LibreOffice。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade
</code></pre><p>这样就好了。当你添加上面的仓库然后升级系统，Ubuntu将会自动的下载安装最新的LibreOffice版本。</p><p>Windows和Mac OS X用户可以直接在程序套件中升级或者直接从网页中下载。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/libreoffice-upgrade-ubuntu.png" alt=""></p><p>Enjoy!</p><hr>`,15)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),p(i,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsupdate-to-libreoffice-latest-in-ubuntu-via-ppa/"},{default:u(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsupdate-to-libreoffice-latest-in-ubuntu-via-ppa/",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=e("译者：",-1)),p(i,{href:"https://github.com/scusjs"},{default:u(()=>[...t[2]||(t[2]=[e("SCUSJS",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:u(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),p(i,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const w=a(b,[["render",l]]);export{c as __pageData,w as default};
